// Approach: Stack of open brackets; every closer must match the most recent opener.
// Time O(n), Space O(n)
class Solution {
public:
    bool isValid(string s) {
        string openBrackets;
        for (char ch : s) {
            if (ch == '(' || ch == '[' || ch == '{') {
                openBrackets.push_back(ch);
                continue;
            }
            if (openBrackets.empty()) {
                return false;
            }
            char open = openBrackets.back();
            openBrackets.pop_back();
            bool matches = (ch == ')' && open == '(') ||
                           (ch == ']' && open == '[') ||
                           (ch == '}' && open == '{');
            if (!matches) {
                return false;
            }
        }
        return openBrackets.empty();
    }
};

