                if ((s[i] == '(' && s[i + 1] == ')') || (s[i] == '[' && s[i + 1] == ']') || (s[i] == '{' && s[i + 1] == '}')) {
                    s.erase(i, 2);
                    changed = true;
                    break;
                }
            }
        }
        return s.empty();
    }
};

