// Approach: Scan the grid and flood-fill each unvisited land cell with an explicit stack, counting fills.
// Time O(rows * cols), Space O(rows * cols)
class Solution {
public:
    int numIslands(vector<vector<char>>& grid) {
        int rows = grid.size();
        int cols = rows ? grid[0].size() : 0;
        int islands = 0;
        const int rowStep[4] = {1, -1, 0, 0};
        const int colStep[4] = {0, 0, 1, -1};
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '1') continue;
                islands++;
                grid[r][c] = '0';  // sinking a cell marks it visited
                vector<pair<int, int>> stack = {{r, c}};
                while (!stack.empty()) {
                    auto [row, col] = stack.back();
                    stack.pop_back();
                    for (int d = 0; d < 4; d++) {
                        int nextRow = row + rowStep[d];
                        int nextCol = col + colStep[d];
                        bool inside = nextRow >= 0 && nextRow < rows && nextCol >= 0 &&
                                      nextCol < cols;
                        if (inside && grid[nextRow][nextCol] == '1') {
                            grid[nextRow][nextCol] = '0';
                            stack.push_back({nextRow, nextCol});
                        }
                    }
                }
            }
        }
        return islands;
    }
};

