class Solution {
    public int numIslands(char[][] grid) {
        int m = grid.length, n = m > 0 ? grid[0].length : 0, count = 0;
        int[] dx = {1, -1, 0, 0}, dy = {0, 0, 1, -1};
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != '1') continue;
                count++;
                grid[i][j] = '0';
                Deque<int[]> stack = new ArrayDeque<>();
                stack.push(new int[]{i, j});
                while (!stack.isEmpty()) {
                    int[] cur = stack.pop();
                    for (int d = 0; d < 4; d++) {
                        int a = cur[0] + dx[d], b = cur[1] + dy[d];
                        if (a >= 0 && a < m && b >= 0 && b < n && grid[a][b] == '1') { grid[a][b] = '0'; stack.push(new int[]{a, b}); }
                    }
                }
            }
        }
        return count;
    }
}

