// Brute force: time O((R*C)^2), space O(R*C)
class Solution {
public:
    int numIslands(vector<vector<char>>& grid) {
        int rows = grid.size(), cols = rows ? grid[0].size() : 0;
        vector<vector<int>> label(rows, vector<int>(cols, 0));
        int next = 1;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (grid[r][c] == '1') label[r][c] = next++;
        int dy[4] = {1, -1, 0, 0}, dx[4] = {0, 0, 1, -1};
        bool changed = true;
        while (changed) {
            changed = false;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!label[r][c]) continue;
                    for (int k = 0; k < 4; k++) {
                        int ny = r + dy[k], nx = c + dx[k];
                        if (ny >= 0 && ny < rows && nx >= 0 && nx < cols && label[ny][nx] && label[ny][nx] < label[r][c]) {
                            label[r][c] = label[ny][nx];
                            changed = true;
                        }
                    }
                }
            }
        }
        set<int> roots;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (label[r][c]) roots.insert(label[r][c]);
        return (int)roots.size();
    }
};

