// Approach: Count letters of s up and letters of t down in one 256-entry table; the strings are anagrams when every count returns to zero.
// Time O(n), Space O(1)
class Solution {
public:
    bool isAnagram(string s, string t) {
        if (s.size() != t.size()) return false;
        int count[256] = {};
        for (size_t i = 0; i < s.size(); i++) {
            count[(unsigned char)s[i]]++;
            count[(unsigned char)t[i]]--;
        }
        for (int c : count) if (c != 0) return false;
        return true;
    }
};

