// Approach: Count nums1 in a hash map, consume matching counts while scanning nums2, and sort only the matches (at most min(n, m)).
// Time O(n + m + k log k) for k matches, Space O(n)
class Solution {
public:
    vector<int> intersect(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, int> remaining;
        remaining.reserve(nums1.size());
        for (int num : nums1) remaining[num]++;
        vector<int> result;
        for (int num : nums2) {
            auto it = remaining.find(num);
            if (it != remaining.end() && it->second > 0) {
                result.push_back(num);
                it->second--;
            }
        }
        sort(result.begin(), result.end());
        return result;
    }
};

