class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        vector<vector<int>> cur = intervals;
        bool changed = true;
        while (changed) {
            changed = false;
            for (size_t i = 0; i < cur.size() && !changed; i++) {
                for (size_t j = i + 1; j < cur.size(); j++) {
                    if (cur[i][0] <= cur[j][1] && cur[j][0] <= cur[i][1]) {
                        cur[i][0] = min(cur[i][0], cur[j][0]);
                        cur[i][1] = max(cur[i][1], cur[j][1]);
                        cur.erase(cur.begin() + j);
                        changed = true;
                        break;
                    }
                }
            }
        }
        sort(cur.begin(), cur.end());
        return cur;
    }
};

