class Solution {
public:
    int removeDuplicates(vector<int>& nums) {
        if (nums.empty()) {
            return 0;
        }
        int size = nums.size();
        int kept = 1;
        for (int i = 1; i < size; i++) {
            if (nums[i] != nums[kept - 1]) {
                nums[kept] = nums[i];
                kept++;
            }
        }
        return kept;
    }
};

