// Approach: Sliding window valid while at most k characters differ from the most common one.
// Time O(n), Space O(1)
class Solution {
public:
    int characterReplacement(string s, int k) {
        int n = s.size();
        vector<int> counts(26, 0);
        int bestLength = 0;
        int windowStart = 0;
        int maxCount = 0;
        for (int windowEnd = 0; windowEnd < n; windowEnd++) {
            maxCount = max(maxCount, ++counts[s[windowEnd] - 'A']);
            // maxCount never needs to shrink: a smaller value cannot beat bestLength.
            while (windowEnd - windowStart + 1 - maxCount > k) {
                counts[s[windowStart++] - 'A']--;
            }
            bestLength = max(bestLength, windowEnd - windowStart + 1);
        }
        return bestLength;
    }
};

