// Approach: Monotonic stack of (start index, height); popped bars close off rectangles.
// Time O(n), Space O(n)
class Solution {
public:
    int largestRectangleArea(vector<int>& heights) {
        long long bestArea = 0;
        heights.push_back(0);  // sentinel that flushes the stack
        vector<pair<int, int>> stack;
        for (int i = 0; i < (int)heights.size(); i++) {
            int start = i;
            while (!stack.empty() && stack.back().second >= heights[i]) {
                auto [barStart, barHeight] = stack.back();
                stack.pop_back();
                bestArea = max(bestArea, (long long)barHeight * (i - barStart));
                start = barStart;
            }
            stack.push_back({start, heights[i]});
        }
        return bestArea;
    }
};

