// Approach: Bottom-up merge sort: merge runs of length 1, 2, 4, ... by relinking nodes, so no recursion stack is needed.
// Time O(n log n), Space O(1)
ListNode* splitAfter(ListNode* head, int count) {
    for (int i = 1; head && i < count; i++) head = head->next;
    if (!head) return nullptr;
    ListNode* rest = head->next;
    head->next = nullptr;
    return rest;
}

ListNode* mergeInto(ListNode* tail, ListNode* a, ListNode* b) {
    while (a && b) {
        if (a->val <= b->val) { tail->next = a; a = a->next; }
        else { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    while (tail->next) tail = tail->next;
    return tail;
}

class Solution {
public:
    ListNode* sortList(ListNode* head) {
        int n = 0;
        for (ListNode* p = head; p; p = p->next) n++;
        ListNode dummy(0);
        dummy.next = head;
        for (int step = 1; step < n; step <<= 1) {
            ListNode* prev = &dummy;
            ListNode* cur = dummy.next;
            while (cur) {
                ListNode* left = cur;
                ListNode* right = splitAfter(left, step);
                cur = splitAfter(right, step);
                prev = mergeInto(prev, left, right);
            }
        }
        return dummy.next;
    }
};

