// Approach: Find each group's k-th node, reverse the group in place and relink it.
// Time O(n), Space O(1)
class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        ListNode dummy(0);
        dummy.next = head;
        ListNode* groupPrev = &dummy;
        while (true) {
            ListNode* kth = groupPrev;
            for (int i = 0; i < k; i++) {
                kth = kth->next;
                if (!kth) {
                    return dummy.next;
                }
            }
            ListNode* groupNext = kth->next;
            ListNode* previous = groupNext;
            ListNode* node = groupPrev->next;
            while (node != groupNext) {
                ListNode* next = node->next;
                node->next = previous;
                previous = node;
                node = next;
            }
            ListNode* groupFirst = groupPrev->next;
            groupPrev->next = kth;
            groupPrev = groupFirst;
        }
    }
};

