// Approach: Count frequencies, then use nth_element to partition the k most frequent (ties by smaller value) and sort just those k.
// Time O(n + d + k log k) average, d distinct values, Space O(d)
class Solution {
public:
    vector<int> topKFrequent(vector<int>& nums, int k) {
        unordered_map<int, int> frequency;
        for (int value : nums) frequency[value]++;
        vector<pair<int, int>> items;  // (count, value)
        items.reserve(frequency.size());
        for (const auto& entry : frequency) items.push_back({entry.second, entry.first});
        auto better = [](const pair<int, int>& a, const pair<int, int>& b) {
            if (a.first != b.first) return a.first > b.first;
            return a.second < b.second;
        };
        if ((size_t)k < items.size()) nth_element(items.begin(), items.begin() + k, items.end(), better);
        items.resize(min((size_t)k, items.size()));
        sort(items.begin(), items.end(), better);
        vector<int> result;
        for (const auto& item : items) result.push_back(item.second);
        return result;
    }
};

