// Approach: Lagrange four-square theorem with Legendre three-square test: the answer is 1, 2, 3 or 4, decided by square checks.
// Time O(sqrt n), Space O(1)
class Solution {
public:
    int numSquares(int n) {
        auto isSquare = [](int x) {
            int r = (int)sqrt((double)x);
            while (r * r > x) r--;
            while ((r + 1) * (r + 1) <= x) r++;
            return r * r == x;
        };
        if (isSquare(n)) return 1;
        while (n % 4 == 0) n /= 4;
        if (n % 8 == 7) return 4;
        for (int i = 1; i * i <= n; i++) {
            if (isSquare(n - i * i)) return 2;
        }
        return 3;
    }
};

