// Approach: Track the max and min product ending at each index, since a negative can flip them.
// Time O(n), Space O(1)
class Solution {
public:
    int maxProduct(vector<int>& nums) {
        long long best = nums[0];
        long long maxEnding = nums[0];
        long long minEnding = nums[0];
        for (int i = 1; i < (int)nums.size(); i++) {
            long long value = nums[i];
            long long candidateA = maxEnding * value;
            long long candidateB = minEnding * value;
            maxEnding = max({value, candidateA, candidateB});
            minEnding = min({value, candidateA, candidateB});
            best = max(best, maxEnding);
        }
        return best;
    }
};

