// Approach: DP over one row: the side ending at a cell is 1 + the minimum of its up, left and diagonal neighbours.
// Time O(rows * cols), Space O(cols)
class Solution {
public:
    int maximalSquare(vector<vector<char>>& matrix) {
        if (matrix.empty()) return 0;
        int rows = matrix.size(), cols = matrix[0].size(), best = 0;
        vector<int> dp(cols + 1, 0);
        for (int i = 0; i < rows; i++) {
            int diag = 0;
            for (int j = 1; j <= cols; j++) {
                int up = dp[j];
                if (matrix[i][j - 1] == '1') {
                    dp[j] = 1 + min({dp[j], dp[j - 1], diag});
                    best = max(best, dp[j]);
                } else {
                    dp[j] = 0;
                }
                diag = up;
            }
        }
        return best * best;
    }
};

