            int currentSum = 0;
            for (int x : nums) {
                if (currentSum + x > maxSum) {
                    parts++;
                    currentSum = x;
                } else {
                    currentSum += x;
                }
            }
            if (parts <= k) {
                high = maxSum;
            } else {
                low = maxSum + 1;
            }
        }
        return low;
    }
};

