// Approach: Backtracking over rows with bitmasks for used columns and both diagonals.
// Time O(n!), Space O(n)
int countPlacements(int fullMask, int columns, int diagonal, int antiDiagonal) {
    if (columns == fullMask) return 1;
    int total = 0;
    int available = fullMask & ~(columns | diagonal | antiDiagonal);
    while (available) {
        int bit = available & -available;
        available -= bit;
        total += countPlacements(fullMask, columns | bit, ((diagonal | bit) << 1) & fullMask,
                                 (antiDiagonal | bit) >> 1);
    }
    return total;
}

class Solution {
public:
    int totalNQueens(int n) {
        return countPlacements((1 << n) - 1, 0, 0, 0);
    }
};

