        for (int c = 0; c < n; c++) {
            bool ok = true;
            for (int r = 0; r < row; r++)
                if (col[r] == c || abs(col[r] - c) == row - r) { ok = false; break; }
            if (!ok) continue;
            col[row] = c;
            total += place(col, row + 1, n);
        }
        return total;
    }
};

