// Approach: Two pointers from both ends, always moving the shorter wall inward.
// Time O(n), Space O(1)
class Solution {
public:
    int maxArea(vector<int>& height) {
        int left = 0;
        int right = (int)height.size() - 1;
        int bestArea = 0;
        while (left < right) {
            int area = (right - left) * min(height[left], height[right]);
            bestArea = max(bestArea, area);
            if (height[left] < height[right]) {
                left++;
            } else {
                right--;
            }
        }
        return bestArea;
    }
};

