// Approach: Record each letter's last index, then cut whenever the scan reaches the part's end.
// Time O(n), Space O(1)
class Solution {
public:
    vector<int> partitionLabels(string s) {
        int n = s.size();
        int lastIndex[26];
        for (int i = 0; i < n; i++) {
            lastIndex[s[i] - 'a'] = i;
        }
        vector<int> sizes;
        int partStart = 0;
        int partEnd = 0;
        for (int i = 0; i < n; i++) {
            partEnd = max(partEnd, lastIndex[s[i] - 'a']);
            if (i == partEnd) {
                sizes.push_back(i - partStart + 1);
                partStart = i + 1;
            }
        }
        return sizes;
    }
};

