// Brute force: time O(n^2), space O(n)
class Solution {
public:
    int candy(vector<int>& ratings) {
        int n = ratings.size();
        vector<int> give(n, 1);
        bool changed = true;
        while (changed) {
            changed = false;
            for (int i = 0; i < n; i++) {
                if (i > 0 && ratings[i] > ratings[i - 1] && give[i] <= give[i - 1]) {
                    give[i] = give[i - 1] + 1;
                    changed = true;
                }
                if (i + 1 < n && ratings[i] > ratings[i + 1] && give[i] <= give[i + 1]) {
                    give[i] = give[i + 1] + 1;
                    changed = true;
                }
            }
        }
        int total = 0;
        for (int x : give) total += x;
        return total;
    }
};

