class Solution {
    static int hnStep(long x) {
        int total = 0;
        while (x > 0) {
            int d = (int) (x % 10);
            total += d * d;
            x /= 10;
        }
        return total;
    }

    public boolean isHappy(int n) {
        long slow = n, fast = hnStep(n);
        while (fast != 1 && slow != fast) {
            slow = hnStep(slow);
            fast = hnStep(hnStep(fast));
        }
        return fast == 1;
    }
}

