class Solution {
public:
    bool isHappy(int n) {
        vector<long long> seen;
        long long x = n;
        while (x != 1) {
            if (find(seen.begin(), seen.end(), x) != seen.end()) return false;
            seen.push_back(x);
            long long total = 0;
            while (x > 0) {
                total += (x % 10) * (x % 10);
                x /= 10;
            }
            x = total;
        }
        return true;
    }
};

