// Approach: Add each symbol's value, subtracting it when a larger symbol follows.
// Time O(n), Space O(1)
class Solution {
public:
    int romanToInt(string s) {
        auto valueOf = [](char symbol) {
            switch (symbol) {
                case 'I': return 1;
                case 'V': return 5;
                case 'X': return 10;
                case 'L': return 50;
                case 'C': return 100;
                case 'D': return 500;
                default: return 1000;
            }
        };
        int total = 0;
        for (size_t i = 0; i < s.size(); i++) {
            if (i + 1 < s.size() && valueOf(s[i]) < valueOf(s[i + 1])) {
                total -= valueOf(s[i]);
            } else {
                total += valueOf(s[i]);
            }
        }
        return total;
    }
};

