        while (remaining > 0) {
            reversed = reversed * 10 + remaining % 10;
            remaining /= 10;
        }
        if (negative) {
            reversed = -reversed;
        }
        return (reversed < INT_MIN || reversed > INT_MAX) ? 0 : reversed;
    }
};

