// Approach: Walk the border layer by layer, shrinking the top, bottom, left and right bounds.
// Time O(m * n), Space O(1) extra (excluding output)
class Solution {
public:
    vector<int> spiralOrder(vector<vector<int>>& matrix) {
        vector<int> result;
        if (matrix.empty()) return result;
        int top = 0;
        int bottom = matrix.size() - 1;
        int left = 0;
        int right = matrix[0].size() - 1;
        while (top <= bottom && left <= right) {
            for (int j = left; j <= right; j++) result.push_back(matrix[top][j]);
            for (int i = top + 1; i <= bottom; i++) result.push_back(matrix[i][right]);
            // the last two sides only exist when the layer has more than one row and column
            if (top < bottom && left < right) {
                for (int j = right - 1; j >= left; j--) result.push_back(matrix[bottom][j]);
                for (int i = bottom - 1; i > top; i--) result.push_back(matrix[i][left]);
            }
            top++;
            bottom--;
            left++;
            right--;
        }
        return result;
    }
};

