class Solution {
    public boolean wordBreak(String s, String wordDict) {
        java.util.Set<String> words = new java.util.HashSet<>();
        java.util.Set<Integer> lens = new java.util.HashSet<>();
        for (String w : wordDict.trim().split("\\s+")) {
            if (!w.isEmpty()) {
                words.add(w);
                lens.add(w.length());
            }
        }
        int n = s.length();
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int i = 1; i <= n; i++) {
            for (int l : lens) {
                if (l <= i && dp[i - l] && words.contains(s.substring(i - l, i))) {
                    dp[i] = true;
                    break;
                }
            }
        }
        return dp[n];
    }
}

