// Approach: Manacher: each center with radius r contributes (r + 1) / 2 palindromes, found in linear time.
// Time O(n), Space O(n)
class Solution {
public:
    int countSubstrings(string s) {
        string t = "^";
        for (char ch : s) { t += '#'; t += ch; }
        t += "#$";
        int m = t.size(), center = 0, right = 0, total = 0;
        vector<int> radius(m, 0);
        for (int i = 1; i < m - 1; i++) {
            if (i < right) radius[i] = min(right - i, radius[2 * center - i]);
            while (t[i + radius[i] + 1] == t[i - radius[i] - 1]) radius[i]++;
            if (i + radius[i] > right) { center = i; right = i + radius[i]; }
            total += (radius[i] + 1) / 2;
        }
        return total;
    }
};

