// Approach: Reduce to counting subsets that sum to (total + target) / 2, using 0/1 knapsack.
// Time O(n * sum), Space O(sum)
class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int target) {
        int total = 0;
        for (int x : nums) {
            total += x;
        }
        // With positives P and negatives N: P - N = target and P + N = total.
        if (abs(target) > total || (total + target) % 2 != 0) {
            return 0;
        }
        int subsetSum = (total + target) / 2;
        vector<long long> ways(subsetSum + 1, 0);
        ways[0] = 1;
        for (int x : nums) {
            for (int sum = subsetSum; sum >= x; sum--) {
                ways[sum] += ways[sum - x];
            }
        }
        return ways[subsetSum];
    }
};

