// Approach: Backtracking over sorted candidates, reusing the same index and pruning once a value exceeds the remainder.
// Time O(N^(target / min candidate)) in the worst case, Space O(target / min candidate) recursion depth
void collectCombinations(const vector<int>& candidates, int start, int remaining,
                         vector<int>& current, vector<vector<int>>& result) {
    if (remaining == 0) {
        result.push_back(current);
        return;
    }
    for (int i = start; i < (int)candidates.size(); i++) {
        if (candidates[i] > remaining) break;
        current.push_back(candidates[i]);
        collectCombinations(candidates, i, remaining - candidates[i], current, result);
        current.pop_back();
    }
}

