static void comboGo(int[] cands, int start, int left, List<Integer> cur, List<int[]> out) {
    if (left == 0) {
        out.add(cur.stream().mapToInt(Integer::intValue).toArray());
        return;
    }
    for (int j = start; j < cands.length; j++) {
        if (cands[j] > left) break;
        cur.add(cands[j]);
        comboGo(cands, j, left - cands[j], cur, out);
        cur.remove(cur.size() - 1);
    }
}

