        for (int i = 0; i < nums.length; i++) a[i + 1] = nums[i];
        // dp[l][r]: best coins bursting everything strictly between l and r
        int[][] dp = new int[n][n];
        for (int len = 2; len < n; len++) {
            for (int l = 0; l + len < n; l++) {
                int r = l + len;
                for (int k = l + 1; k < r; k++) // k is the LAST balloon burst in (l, r)
                    dp[l][r] = Math.max(dp[l][r], dp[l][k] + a[l] * a[k] * a[r] + dp[k][r]);
            }
        }
        return dp[0][n - 1];
    }
}

