            int d = cur[0], u = cur[1];
            if (d > dist[u]) continue;
            for (int[] e : adj[u]) {
                if (d + e[1] < dist[e[0]]) {
                    dist[e[0]] = d + e[1];
                    pq.add(new int[]{dist[e[0]], e[0]});
