// Approach: Greedy change-making that tracks the count of $5 and $10 bills held.
// Time O(n), Space O(1)
class Solution {
public:
    bool lemonadeChange(vector<int>& bills) {
        int fives = 0;
        int tens = 0;
        for (int bill : bills) {
            if (bill == 5) {
                fives++;
            } else if (bill == 10) {
                if (fives == 0) {
                    return false;
                }
                fives--;
                tens++;
            } else if (tens > 0 && fives > 0) {
                // Prefer 10 + 5 so the more flexible 5s are kept.
                tens--;
                fives--;
            } else if (fives >= 3) {
                fives -= 3;
            } else {
                return false;
            }
        }
        return true;
    }
};

