        for (int c : counts) mx = Math.max(mx, c);
        int numMax = 0;
        for (int c : counts) if (c == mx) numMax++;
        // (mx - 1) full frames of n + 1 slots, plus the final row of max-count tasks
        return Math.max(tasks.length, (mx - 1) * (n + 1) + numMax);
    }
}

