// Brute force: time O(2^n) worst case, space O(h)
class Solution {
public:
    int rob(TreeNode* root) {
        if (!root) return 0;
        // option 1: rob this node, so skip both children and recurse on grandchildren
        int take = root->val;
        if (root->left) take += rob(root->left->left) + rob(root->left->right);
        if (root->right) take += rob(root->right->left) + rob(root->right->right);
        // option 2: skip this node
        int skip = rob(root->left) + rob(root->right);
        return max(take, skip);
    }
};

