// Approach: Greedy two-pointer matching that backtracks to the most recent '*' on a mismatch.
// Time O(n * m), Space O(1)
class Solution {
public:
    bool isMatch(string s, string p) {
        int n = s.size();
        int m = p.size();
        int i = 0;
        int j = 0;
        int starIndex = -1;
        int matchedUpTo = 0;
        while (i < n) {
            if (j < m && (p[j] == '?' || p[j] == s[i])) {
                i++;
                j++;
            } else if (j < m && p[j] == '*') {
                starIndex = j;
                matchedUpTo = i;
                j++;
            } else if (starIndex != -1) {
                // Let the last '*' absorb one more character of s.
                j = starIndex + 1;
                matchedUpTo++;
                i = matchedUpTo;
            } else {
                return false;
            }
        }
        while (j < m && p[j] == '*') {
            j++;
        }
        return j == m;
    }
};

