// Approach: Treat 0 as -1 and store the first index of each running balance in a hash map.
// Time O(n), Space O(n)
class Solution {
public:
    int findMaxLength(vector<int>& nums) {
        int n = nums.size();
        unordered_map<int, int> firstSeenAt;
        firstSeenAt[0] = -1;
        int balance = 0;
        int bestLength = 0;
        for (int i = 0; i < n; i++) {
            balance += nums[i] == 1 ? 1 : -1;
            auto it = firstSeenAt.find(balance);
            if (it != firstSeenAt.end()) {
                bestLength = max(bestLength, i - it->second);
            } else {
                firstSeenAt[balance] = i;
            }
        }
        return bestLength;
    }
};

