// Approach: Track digits already seen in each row, column and 3x3 box.
// Time O(1), Space O(1)
class Solution {
public:
    bool isValidSudoku(vector<vector<char>>& board) {
        bool inRow[9][9] = {};
        bool inCol[9][9] = {};
        bool inBox[9][9] = {};
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') {
                    continue;
                }
                int digit = board[r][c] - '1';
                int box = (r / 3) * 3 + c / 3;
                if (inRow[r][digit] || inCol[c][digit] || inBox[box][digit]) {
                    return false;
                }
                inRow[r][digit] = true;
                inCol[c][digit] = true;
                inBox[box][digit] = true;
            }
        }
        return true;
    }
};

