                        int nj = j + dj;
                        if (ni >= 0 && ni < m && nj >= 0 && nj < n) {
                            liveNeighbors += board[ni][nj] & 1;
                        }
                    }
                }
                if (liveNeighbors == 3 || (board[i][j] && liveNeighbors == 2)) {
                    board[i][j] |= 2;
                }
            }
        }
        for (auto& row : board) {
            for (int& cell : row) cell >>= 1;
        }
    }
};

