// Brute force: time O((m*n)^2), space O(m*n) (flood every region and test it for a border cell)
class Solution {
public:
    void solve(vector<vector<char>>& board) {
        int m = board.size(), n = m ? board[0].size() : 0;
        vector<vector<int>> seen(m, vector<int>(n, 0));
        int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (board[i][j] != 'O' || seen[i][j]) continue;
                vector<pair<int, int>> cells = {{i, j}};
                seen[i][j] = 1;
                bool border = false;
                for (size_t k = 0; k < cells.size(); k++) {
                    auto [r, c] = cells[k];
                    if (r == 0 || c == 0 || r == m - 1 || c == n - 1) border = true;
                    for (int d = 0; d < 4; d++) {
                        int a = r + dr[d], b = c + dc[d];
                        if (a >= 0 && b >= 0 && a < m && b < n && board[a][b] == 'O' && !seen[a][b]) {
                            seen[a][b] = 1;
                            cells.push_back({a, b});
                        }
                    }
                }
                if (!border) for (auto [r, c] : cells) board[r][c] = 'X';
            }
    }
};

