void explore(int node, int dst, int edgesLeft, long long cost, const vector<vector<int>> &flights, long long &best) {
    if (cost >= best) return;
    if (node == dst) { best = cost; return; }
    if (edgesLeft == 0) return;
    for (auto &f : flights)
        if (f[0] == node) explore(f[1], dst, edgesLeft - 1, cost + f[2], flights, best);
}

