// Brute force: time O(maxEffort * m * n), space O(m*n)
class Solution {
public:
    int minimumEffortPath(vector<vector<int>>& heights) {
        int m = heights.size(), n = heights[0].size();
        int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
        // try each effort limit in turn; the first one that lets us reach the end is the answer
        for (int limit = 0;; limit++) {
            vector<vector<char>> seen(m, vector<char>(n, 0));
            vector<pair<int, int>> st = {{0, 0}};
            seen[0][0] = 1;
            while (!st.empty()) {
                auto [i, j] = st.back();
                st.pop_back();
                if (i == m - 1 && j == n - 1) return limit;
                for (int d = 0; d < 4; d++) {
                    int a = i + dx[d], b = j + dy[d];
                    if (a < 0 || a >= m || b < 0 || b >= n || seen[a][b]) continue;
                    if (abs(heights[a][b] - heights[i][j]) > limit) continue;
                    seen[a][b] = 1;
                    st.push_back({a, b});
