// Approach: Build column heights row by row and solve largest-rectangle-in-histogram with a monotonic stack.
// Time O(rows * cols), Space O(cols)
class Solution {
public:
    int maximalRectangle(vector<vector<int>>& matrix) {
        if (matrix.empty()) return 0;
        int cols = matrix[0].size();
        int bestArea = 0;
        vector<int> heights(cols, 0);
        for (const auto& row : matrix) {
            for (int j = 0; j < cols; j++) {
                heights[j] = row[j] == 1 ? heights[j] + 1 : 0;
            }
            vector<int> stack;  // indices with strictly increasing heights
            for (int j = 0; j <= cols; j++) {
                int current = j < cols ? heights[j] : 0;
                while (!stack.empty() && heights[stack.back()] >= current) {
                    int height = heights[stack.back()];
                    stack.pop_back();
                    int leftEdge = stack.empty() ? -1 : stack.back();
                    bestArea = max(bestArea, height * (j - leftEdge - 1));
                }
                stack.push_back(j);
            }
        }
        return bestArea;
    }
};

