// Approach: Kadane for max and min subarrays; the circular best is total minus the min subarray.
// Time O(n), Space O(1)
class Solution {
public:
    int maxSubarraySumCircular(vector<int>& nums) {
        long long total = 0;
        long long currentMax = 0;
        long long currentMin = 0;
        long long bestMax = nums[0];
        long long bestMin = nums[0];
        for (int num : nums) {
            total += num;
            currentMax = max(currentMax + num, (long long)num);
            bestMax = max(bestMax, currentMax);
            currentMin = min(currentMin + num, (long long)num);
            bestMin = min(bestMin, currentMin);
        }
        // All-negative input: the wrapped case would select an empty subarray.
        if (bestMax < 0) return bestMax;
        return max(bestMax, total - bestMin);
    }
};

