    int bestLen = s.length() + 1, bestStart = 0, left = 0;
    for (int right = 0; right < s.length(); right++) {
        char ch = s.charAt(right);
        if (need.getOrDefault(ch, 0) > 0) missing--;
        need.merge(ch, -1, Integer::sum);
        if (missing == 0) {
            while (need.get(s.charAt(left)) < 0) {
                need.merge(s.charAt(left), 1, Integer::sum);
                left++;
            }
            if (right - left + 1 < bestLen) {
                bestLen = right - left + 1;
                bestStart = left;
            }
            need.merge(s.charAt(left), 1, Integer::sum);
            missing++;
            left++;
        }
    }
    return bestLen > s.length() ? "" : s.substring(bestStart, bestStart + bestLen);
