// Approach: Keep a two-way character mapping and reject any conflict.
// Time O(n), Space O(1) for a fixed alphabet
class Solution {
public:
    bool isIsomorphic(string s, string t) {
        unordered_map<char, char> sToT;
        unordered_map<char, char> tToS;
        int n = s.size();
        for (int i = 0; i < n; i++) {
            char from = s[i];
            char to = t[i];
            if (sToT.count(from) && sToT[from] != to) {
                return false;
            }
            if (tToS.count(to) && tToS[to] != from) {
                return false;
            }
            sToT[from] = to;
            tToS[to] = from;
        }
        return true;
    }
};

