// Approach: Binary search on the value; count entries <= mid with a staircase walk from the bottom-left corner.
// Time O((rows + cols) log(max - min)), Space O(1)
class Solution {
public:
    int kthSmallest(vector<vector<int>>& matrix, int k) {
        int rows = matrix.size(), cols = matrix[0].size();
        int low = matrix[0][0], high = matrix[rows - 1][cols - 1];
        while (low < high) {
            int mid = low + (high - low) / 2;
            int count = 0, r = rows - 1, c = 0;
            while (r >= 0 && c < cols) {
                if (matrix[r][c] <= mid) { count += r + 1; c++; }
                else r--;
            }
            if (count >= k) high = mid;
            else low = mid + 1;
        }
        return low;
    }
};

