// Optimised: O(n) time, O(1) space
class Solution {
public:
    vector<int> majorityElement(vector<int>& nums) {
        int c1 = 0, c2 = 0, v1 = 0, v2 = 1;
        for (int x : nums) {
            if (x == v1) c1++;
            else if (x == v2) c2++;
            else if (c1 == 0) { v1 = x; c1 = 1; }
            else if (c2 == 0) { v2 = x; c2 = 1; }
            else { c1--; c2--; }
        }
        int n1 = 0, n2 = 0, n = nums.size();
        for (int x : nums) {
            if (x == v1) n1++;
            else if (x == v2) n2++;
        }
        vector<int> out;
        if (n1 > n / 3) out.push_back(v1);
        if (n2 > n / 3) out.push_back(v2);
        sort(out.begin(), out.end());
        return out;
    }
};

