// Optimised: O(n log m) time, O(1) space
class Solution {
public:
    int nthRoot(int n, int m) {
        long long lo = 1, hi = m;
        while (lo <= hi) {
            long long mid = lo + (hi - lo) / 2, power = 1;
            bool tooBig = false;
            for (int i = 0; i < n; i++) {
                power *= mid;
                if (power > m) { tooBig = true; break; }
            }
            if (!tooBig && power == m) return (int)mid;
            if (tooBig) hi = mid - 1;
            else lo = mid + 1;
        }
        return -1;
    }
};

// Optimised: O(n log(max day)) time, O(1) space
class Solution {
public:
    int minDays(vector<int>& bloomDay, int m, int k) {
        long long n = bloomDay.size();
        if ((long long)m * k > n) return -1;
        auto enough = [&](int day) {
            int made = 0, run = 0;
            for (int b : bloomDay) {
                if (b <= day) {
                    if (++run == k) { made++; run = 0; }
                } else {
                    run = 0;
                }
            }
            return made >= m;
        };
        int lo = *min_element(bloomDay.begin(), bloomDay.end());
        int hi = *max_element(bloomDay.begin(), bloomDay.end());
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (enough(mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

// Optimised: O(n log(max)) time, O(1) space
class Solution {
public:
    int smallestDivisor(vector<int>& nums, int threshold) {
        int lo = 1, hi = *max_element(nums.begin(), nums.end());
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            long long total = 0;
            for (int x : nums) total += (x + mid - 1) / mid;
            if (total <= threshold) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

// Optimised: O(n log n + n log(range)) time, O(1) space
class Solution {
public:
    int aggressiveCows(vector<int>& stalls, int cows) {
        sort(stalls.begin(), stalls.end());
        auto canPlace = [&](int dist) {
            int placed = 1, last = stalls[0];
            for (size_t i = 1; i < stalls.size(); i++)
                if (stalls[i] - last >= dist) { placed++; last = stalls[i]; }
            return placed >= cows;
        };
        int lo = 1, hi = stalls.back() - stalls.front();
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            if (canPlace(mid)) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
};

// Optimised: O(log(min(n, m))) time, O(1) space
class Solution {
public:
    int kthElement(vector<int>& a, vector<int>& b, int k) {
        if (a.size() > b.size()) swap(a, b);
        int n = a.size(), m = b.size();
        int lo = max(0, k - m), hi = min(k, n);                    // how many elements to take from a
        while (lo <= hi) {
            int i = lo + (hi - lo) / 2, j = k - i;
            int aLeft = i > 0 ? a[i - 1] : INT_MIN, aRight = i < n ? a[i] : INT_MAX;
            int bLeft = j > 0 ? b[j - 1] : INT_MIN, bRight = j < m ? b[j] : INT_MAX;
            if (aLeft > bRight) hi = i - 1;
            else if (bLeft > aRight) lo = i + 1;
            else return max(aLeft, bLeft);
        }
        return -1;
    }
};

// Approach: Staircase walk from the top-right: step left while the cell is 1, otherwise step down; the last row that moved left holds the most ones.
// Time O(rows + cols), Space O(1)
class Solution {
public:
    int rowWithMaxOnes(vector<vector<int>>& matrix) {
        int rows = matrix.size();
        if (rows == 0) return 0;
        int col = (int)matrix[0].size() - 1, best = 0;
        for (int r = 0; r < rows && col >= 0; ) {
            if (matrix[r][col] == 1) { best = r; col--; }  // this row has more ones than any row before it
            else r++;
        }
        return best;
    }
};

// Optimised: O(r + c) time, O(1) space
class Solution {
public:
    bool searchMatrix(vector<vector<int>>& matrix, int target) {
        int r = 0, c = (int)matrix[0].size() - 1;                  // start at the top-right corner
        while (r < (int)matrix.size() && c >= 0) {
            if (matrix[r][c] == target) return true;
            if (matrix[r][c] > target) c--;
            else r++;
        }
        return false;
    }
};

// Optimised: O(log n) time, O(1) space
class Solution {
public:
    int findKthPositive(vector<int>& arr, int k) {
        int lo = 0, hi = arr.size();
        while (lo < hi) {                                          // count elements with fewer than k numbers missing before them
            int mid = lo + (hi - lo) / 2;
            if (arr[mid] - (mid + 1) < k) lo = mid + 1;
            else hi = mid;
        }
        return lo + k;
    }
};

// Optimised: O(r log c log(range)) time, O(1) space
class Solution {
public:
    int findMedian(vector<vector<int>>& matrix) {
        int rows = matrix.size(), cols = matrix[0].size();
        int lo = INT_MAX, hi = INT_MIN;
        for (const auto& row : matrix) {
            lo = min(lo, row.front());
            hi = max(hi, row.back());
        }
        int need = (rows * cols) / 2 + 1;                          // the median is the smallest value with >= need elements <= it
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2, count = 0;
            for (const auto& row : matrix)
                count += upper_bound(row.begin(), row.end(), mid) - row.begin();
            if (count >= need) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

// Optimised: O(n * 2^n) time, O(n) recursion depth (output excluded) space
void subsetsGo(const vector<int> &nums, int i, vector<int> &cur, vector<vector<int>> &out) {
    if (i == (int)nums.size()) {
        out.push_back(cur);
        return;
    }
    subsetsGo(nums, i + 1, cur, out);              // skip nums[i]
    cur.push_back(nums[i]);
    subsetsGo(nums, i + 1, cur, out);              // take nums[i]
    cur.pop_back();
}

class Solution {
public:
    vector<vector<int>> subsets(vector<int>& nums) {
        vector<vector<int>> out;
        vector<int> cur;
        subsetsGo(nums, 0, cur, out);
        return out;
    }
};

// Optimised: O(n * 2^n) time, O(n) space
void subsetsUniqueGo(const vector<int> &nums, int start, vector<int> &cur, vector<vector<int>> &out) {
    out.push_back(cur);
    for (int i = start; i < (int)nums.size(); i++) {
        if (i > start && nums[i] == nums[i - 1]) continue;   // same value at the same depth: skip
        cur.push_back(nums[i]);
        subsetsUniqueGo(nums, i + 1, cur, out);
        cur.pop_back();
    }
}

class Solution {
public:
    vector<vector<int>> subsetsWithDup(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        vector<vector<int>> out;
