// Optimised: O(n^2) time, O(n) space
class Solution {
public:
    string getPermutation(int n, int k) {
        vector<int> digits;
        int fact = 1;
        for (int i = 1; i < n; i++) {
            fact *= i;
            digits.push_back(i);
        }
        digits.push_back(n);
        k--;                                          // zero-based rank
        string out;
        while (true) {
            int idx = k / fact;
            out += to_string(digits[idx]);
            digits.erase(digits.begin() + idx);
            if (digits.empty()) break;
            k %= fact;
            fact /= digits.size();
        }
        return out;
    }
};

// Optimised: O(4^(n*n)) worst case time, O(n*n) space
void mazeGo(const vector<vector<int>> &maze, int r, int c, string &path, vector<vector<bool>> &seen, vector<string> &out) {
    int n = maze.size();
    if (r == n - 1 && c == n - 1) {
        out.push_back(path);
        return;
    }
    static const int dr[4] = {1, 0, 0, -1}, dc[4] = {0, -1, 1, 0};
    static const char mv[4] = {'D', 'L', 'R', 'U'};
    for (int d = 0; d < 4; d++) {
        int a = r + dr[d], b = c + dc[d];
        if (a < 0 || b < 0 || a >= n || b >= n || !maze[a][b] || seen[a][b]) continue;
        seen[a][b] = true;
        path.push_back(mv[d]);
        mazeGo(maze, a, b, path, seen, out);
        path.pop_back();
        seen[a][b] = false;
    }
}

class Solution {
public:
    vector<string> findPath(vector<vector<int>>& maze) {
        int n = maze.size();
        vector<string> out;
        if (!maze[0][0] || !maze[n - 1][n - 1]) return out;
        vector<vector<bool>> seen(n, vector<bool>(n, false));
        seen[0][0] = true;
        string path;
        mazeGo(maze, 0, 0, path, seen, out);
        return out;
    }
};

// Optimised: O(m^n) time, O(n) space
bool colorGo(const vector<vector<int>> &g, int v, int m, vector<int> &color) {
    int n = g.size();
    if (v == n) return true;
    for (int c = 1; c <= m; c++) {
        bool ok = true;
        for (int u = 0; u < v && ok; u++)
            if (g[v][u] && color[u] == c) ok = false;
        if (!ok) continue;
        color[v] = c;
        if (colorGo(g, v + 1, m, color)) return true;
        color[v] = 0;
    }
    return false;
}

class Solution {
public:
    bool graphColoring(vector<vector<int>>& graph, int m) {
        vector<int> color(graph.size(), 0);
        return colorGo(graph, 0, m, color);
    }
};

// Optimised: O(n * F(n)) (Fibonacci many strings) time, O(n) space
void binaryGo(int n, string &cur, vector<string> &out) {
    if ((int)cur.size() == n) {
        out.push_back(cur);
        return;
    }
    cur.push_back('0');
    binaryGo(n, cur, out);
    cur.pop_back();
    if (cur.empty() || cur.back() != '1') {      // a 1 may only follow a 0 (or start the string)
        cur.push_back('1');
        binaryGo(n, cur, out);
        cur.pop_back();
    }
}

class Solution {
public:
    vector<string> generateBinaryStrings(int n) {
        vector<string> out;
        string cur;
        binaryGo(n, cur, out);
        return out;
    }
};

// Optimised: O(n * k) time, O(k) space
class Solution {
public:
    int countSubsequences(vector<int>& nums, int k) {
        vector<long long> ways(k + 1, 0);              // ways[s] = subsequences seen so far that sum to s
        ways[0] = 1;
        for (int x : nums)
            for (int s = k; s >= x; s--) ways[s] += ways[s - x];
        return (int)ways[k];
    }
};

// Optimised: O(n * 2^n) time, O(n) space
void subseqGo(const vector<int> &nums, int i, int left, vector<int> &cur, vector<vector<int>> &out) {
    if (left == 0 && !cur.empty()) out.push_back(cur);
    if (left <= 0) return;
    for (int j = i; j < (int)nums.size(); j++) {
        if (nums[j] > left) continue;
        cur.push_back(nums[j]);
        subseqGo(nums, j + 1, left - nums[j], cur, out);
        cur.pop_back();
    }
}

class Solution {
public:
    vector<vector<int>> subsequencesWithSum(vector<int>& nums, int k) {
        vector<vector<int>> out;
        vector<int> cur;
        subseqGo(nums, 0, k, cur, out);
        return out;
    }
};

