// Optimised: O(d^2) for d digits time, O(1) space
class Solution {
public:
    bool isArmstrong(int n) {
        int digits = 0;
        for (int t = n; t > 0; t /= 10) digits++;
        long long total = 0;
        for (int t = n; t > 0; t /= 10) {
            long long p = 1;
            for (int i = 0; i < digits; i++) p *= t % 10;
            total += p;
        }
        return total == n;
    }
};

// Optimised: O(sqrt n) time, O(number of divisors) space
class Solution {
public:
    vector<int> divisors(int n) {
        vector<int> small, large;
        for (int d = 1; (long long)d * d <= n; d++) {
            if (n % d != 0) continue;
            small.push_back(d);
            if (d != n / d) large.push_back(n / d);
        }
        reverse(large.begin(), large.end());
        small.insert(small.end(), large.begin(), large.end());
        return small;
    }
};

// Optimised: O(sqrt n) time, O(1) space
class Solution {
public:
    bool isPrime(int n) {
        if (n < 2) return false;
        if (n < 4) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;
        for (long long i = 5; i * i <= n; i += 6)
            if (n % i == 0 || n % (i + 2) == 0) return false;
        return true;
    }
};

// Optimised: O(n log n) time, O(n) space
void mergeSortRange(vector<int> &a, vector<int> &tmp, int lo, int hi) {
    if (hi - lo < 2) return;
    int mid = (lo + hi) / 2;
    mergeSortRange(a, tmp, lo, mid);
    mergeSortRange(a, tmp, mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) tmp[k++] = a[i] <= a[j] ? a[i++] : a[j++];
    while (i < mid) tmp[k++] = a[i++];
    while (j < hi) tmp[k++] = a[j++];
    copy(tmp.begin() + lo, tmp.begin() + hi, a.begin() + lo);
}

class Solution {
public:
    vector<int> sortArray(vector<int>& nums) {
        vector<int> tmp(nums.size());
        mergeSortRange(nums, tmp, 0, nums.size());
        return nums;
    }
};

// Optimised: O(n) time, O(n) space
class Solution {
public:
    string removeOuterParentheses(string s) {
        string out;
        int depth = 0;
        for (char c : s) {
            if (c == '(') {
                if (depth++ > 0) out += c;
            } else {
                if (--depth > 0) out += c;
            }
        }
        return out;
    }
};

// Optimised: O(n) time, O(n) space
class Solution {
public:
    string reverseWords(string s) {
        reverse(s.begin(), s.end());
        string out;
        for (size_t i = 0; i < s.size();) {
            while (i < s.size() && s[i] == ' ') i++;
            if (i == s.size()) break;
            size_t j = i;
            while (j < s.size() && s[j] != ' ') j++;
            string word = s.substr(i, j - i);
            reverse(word.begin(), word.end());
            if (!out.empty()) out += ' ';
            out += word;
            i = j;
        }
        return out;
    }
};

// Optimised: O(n) time, O(1) space
class Solution {
public:
    string largestOddNumber(string num) {
        for (int i = (int)num.size() - 1; i >= 0; i--)
            if ((num[i] - '0') % 2 == 1) return num.substr(0, i + 1);
        return "";
    }
};

// Approach: The prefix common to all strings is the prefix common to the lexicographically smallest and largest ones; find both in one linear pass.
// Time O(n * m), Space O(1)
class Solution {
public:
    string longestCommonPrefix(vector<string>& strs) {
        if (strs.empty()) return "";
        const string *smallest = &strs[0], *largest = &strs[0];
        for (const string& s : strs) {
            if (s < *smallest) smallest = &s;
            if (s > *largest) largest = &s;
        }
        size_t i = 0;
        while (i < smallest->size() && i < largest->size() && (*smallest)[i] == (*largest)[i]) i++;
        return smallest->substr(0, i);
    }
};

// Approach: KMP search for goal inside s + s (read through i % n so the doubled string is never built); linear worst case.
// Time O(n), Space O(n)
class Solution {
public:
    bool rotateString(string s, string goal) {
        int n = s.size();
        if (n != (int)goal.size()) return false;
        if (n == 0) return true;
        vector<int> lps(n, 0);
        for (int i = 1, len = 0; i < n; ) {
            if (goal[i] == goal[len]) lps[i++] = ++len;
            else if (len > 0) len = lps[len - 1];
            else lps[i++] = 0;
        }
        for (int i = 0, matched = 0; i < 2 * n - 1; i++) {
            char c = s[i % n];
            while (matched > 0 && c != goal[matched]) matched = lps[matched - 1];
            if (c == goal[matched]) matched++;
            if (matched == n) return true;
        }
        return false;
    }
};

// Optimised: O(n) time, O(1) space
class Solution {
public:
    int maxDepth(string s) {
        int depth = 0, best = 0;
        for (char c : s) {
            if (c == '(') best = max(best, ++depth);
            else if (c == ')') depth--;
        }
        return best;
    }
};

// Optimised: O(n) time, O(1) space
class Solution {
public:
    int myAtoi(string s) {
        size_t i = 0, n = s.size();
        while (i < n && s[i] == ' ') i++;
        int sign = 1;
        if (i < n && (s[i] == '+' || s[i] == '-')) sign = s[i++] == '-' ? -1 : 1;
        long long value = 0;
        while (i < n && isdigit((unsigned char)s[i])) {
            value = value * 10 + (s[i++] - '0');
            if (value > (long long)INT_MAX + 1) break;     // already out of range, stop growing
        }
        value *= sign;
        if (value > INT_MAX) return INT_MAX;
        if (value < INT_MIN) return INT_MIN;
        return (int)value;
    }
};

// Optimised: O(n * length of the terms) time, O(length of a term) space
class Solution {
public:
    string countAndSay(int n) {
        string s = "1";
        for (int step = 1; step < n; step++) {
            string next;
            for (size_t i = 0; i < s.size();) {
                size_t j = i;
                while (j < s.size() && s[j] == s[i]) j++;
                next += to_string(j - i);
                next += s[i];
                i = j;
            }
            s = next;
        }
        return s;
    }
};

// Optimised: O(n + m) time, O(m) space
class Solution {
public:
    int strStr(string haystack, string needle) {
        int n = haystack.size(), m = needle.size();
        vector<int> lps(m, 0);                             // longest proper prefix that is also a suffix
        for (int i = 1, len = 0; i < m;) {
            if (needle[i] == needle[len]) lps[i++] = ++len;
            else if (len > 0) len = lps[len - 1];
            else lps[i++] = 0;
        }
        for (int i = 0, j = 0; i < n;) {
            if (haystack[i] == needle[j]) {
                i++;
                j++;
                if (j == m) return i - m;
            } else if (j > 0) {
                j = lps[j - 1];
            } else {
                i++;
            }
        }
        return -1;
    }
};

// Optimised: O(26 * n^2) time, O(1) space
class Solution {
public:
    int beautySum(string s) {
        int n = s.size(), total = 0;
        for (int i = 0; i < n; i++) {
            int freq[26] = {};
            for (int j = i; j < n; j++) {
                freq[s[j] - 'a']++;
                int hi = 0, lo = INT_MAX;
                for (int f : freq) {
                    if (f == 0) continue;
                    hi = max(hi, f);
                    lo = min(lo, f);
                }
                total += hi - lo;
            }
        }
        return total;
    }
};

// Optimised: O(n log n) time, O(n) space

class Solution {
public:
    int maxMeetings(vector<int>& start, vector<int>& end) {
        int n = start.size();
        vector<pair<int, int>> meetings(n);
        for (int i = 0; i < n; i++) meetings[i] = {end[i], start[i]};
        sort(meetings.begin(), meetings.end());
        int count = 0, lastEnd = -1;
        for (auto& m : meetings) {
            if (m.second > lastEnd) {
                count++;
                lastEnd = m.first;
            }
        }
        return count;
    }
};

// Optimised: O(n log n) time, O(1) extra space

class Solution {
public:
    int minimumPlatforms(vector<int>& arr, vector<int>& dep) {
        sort(arr.begin(), arr.end());
        sort(dep.begin(), dep.end());
        int n = arr.size(), i = 0, j = 0, onPlatform = 0, best = 0;
        while (i < n) {
            if (arr[i] <= dep[j]) {          // next arrival comes before (or when) the earliest departure
                best = max(best, ++onPlatform);
                i++;
            } else {
                onPlatform--;
                j++;
            }
        }
        return best;
    }
};

// Optimised: O(n log n) time, O(n) space

class Solution {
public:
    vector<int> jobSequencing(vector<int>& deadline, vector<int>& profit) {
        int n = deadline.size();
        vector<int> order(n);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) { return profit[a] > profit[b]; });
        vector<int> parent(n + 1);            // parent[t] = latest free slot <= t (0 means none)
        iota(parent.begin(), parent.end(), 0);
        function<int(int)> find = [&](int t) { return parent[t] == t ? t : parent[t] = find(parent[t]); };
        int jobs = 0, total = 0;
        for (int id : order) {
            int slot = find(min(deadline[id], n));
            if (slot > 0) {
                parent[slot] = slot - 1;
                jobs++;
                total += profit[id];
            }
        }
        return {jobs, total};
    }
};

// Optimised: O(n) time, O(n) space

class Solution {
public:
    vector<int> nextSmallerElement(vector<int>& nums) {
        int n = nums.size();
        vector<int> ans(n, -1);
        stack<int> st;                        // indices whose next smaller value is still unknown
        for (int i = 0; i < n; i++) {
            while (!st.empty() && nums[st.top()] > nums[i]) {
                ans[st.top()] = nums[i];
                st.pop();
            }
            st.push(i);
        }
        return ans;
    }
};

// Optimised: O(n) time, O(n) space

class Solution {
public:
    vector<int> stockSpan(vector<int>& prices) {
        int n = prices.size();
        vector<int> span(n);
        stack<int> st;                        // indices with strictly decreasing prices
        for (int i = 0; i < n; i++) {
            while (!st.empty() && prices[st.top()] <= prices[i]) st.pop();
            span[i] = st.empty() ? i + 1 : i - st.top();
            st.push(i);
        }
        return span;
    }
};

// Optimised: O(n) time, O(n) space

class Solution {
public:
    vector<int> maxOfMinimums(vector<int>& nums) {
        int n = nums.size();
        vector<int> left(n, -1), right(n, n);
        stack<int> st;
        for (int i = 0; i < n; i++) {
            while (!st.empty() && nums[st.top()] >= nums[i]) {
                right[st.top()] = i;
                st.pop();
            }
            left[i] = st.empty() ? -1 : st.top();
            st.push(i);
        }
        vector<int> ans(n + 2, 0);            // ans[len] = best minimum over windows of exactly len
        for (int i = 0; i < n; i++) {
            int len = right[i] - left[i] - 1;  // nums[i] is the minimum of a window this long
            ans[len] = max(ans[len], nums[i]);
        }
        for (int len = n - 1; len >= 1; len--) ans[len] = max(ans[len], ans[len + 1]);
        return vector<int>(ans.begin() + 1, ans.begin() + n + 1);
    }
};

// Optimised: O(n) time, O(1) space

class Solution {
public:
    int celebrity(vector<vector<int>>& M) {
        int n = M.size(), cand = 0;
        for (int i = 1; i < n; i++)
            if (M[cand][i]) cand = i;         // cand knows i, so cand cannot be the celebrity
        for (int i = 0; i < n; i++) {
            if (i == cand) continue;
            if (M[cand][i] || !M[i][cand]) return -1;
        }
        return cand;
    }
};

// Optimised: O(1) time, O(1) space

class Solution {
public:
    string intToRoman(int num) {
        const int value[] = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
        const char* symbol[] = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};
        string out;
        for (int i = 0; i < 13; i++)
            while (num >= value[i]) {
